def parse_module(filepath):
    with open(filepath, "r", encoding="utf-8") as f:
        tree = ast.parse(f.read())

    module_name = os.path.basename(filepath).replace(".py", "")
    if module_name.startswith("_") and module_name != "__init__":
        return None

    lines = []
    module_level_doc = ast.get_docstring(tree)
    if module_level_doc:
        lines.append(f"## paket.{module_name}\n{module_level_doc.split('\n')[0]}")
    else:
        lines.append(f"## paket.{module_name}")

    # Constants (Module level)
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            if isinstance(node.value, (ast.Constant, ast.List, ast.Dict, ast.Tuple)):
                name = node.targets[0].id
                if not name.startswith("_"):
                    lines.append(f"- `{name}` — {ast.unparse(node.value)}")

    # Classes and Functions
    classes = {}

    for node in tree.body:
        # Functions
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith("_"):
                sig = f"{'async ' if isinstance(node, ast.AsyncFunctionDef) else ''}{node.name}{ast.unparse(node.args)} -> {ast.unparse(node.returns) if node.returns else 'Any'}"
                # Cleaning up the signature manually to match requirements exactly if ast.unparse is too verbose
                # But let's try to clean it.
                sig = sig.replace(" -> None", "").replace(" -> Any", "")
                # Actually, requirement says: def and trailing : are not part of it.
                # and include type hints and defaults.

                # Let's re-do signature carefully
                sig = f"{'async ' if isinstance(node, ast.AsyncFunctionDef) else ''}{node.name}{ast.unparse(node.args)}"
                if node.returns:
                    sig += f" -> {ast.unparse(node.returns)}"

                doc = get_docstring(node).strip()
                if doc:
                    lines.append(f"- `{sig}` — {doc}")

        # Classes
        elif isinstance(node, ast.ClassDef):
            if not node.name.startswith("_"):
                doc = get_docstring(node).strip()
                lines.append(f"- `class {node.name}` — {doc if doc else ''}")
                classes[node.name] = node

    # Methods (from classes)
    # Re-iterate to find methods inside classes
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if not item.name.startswith("_") and item.name != "__init__":
                        sig = f"{'async ' if isinstance(item, ast.AsyncFunctionDef) else ''}{node.name}.{item.name}{ast.unparse(item.args)}"
                        if item.returns:
                            sig += f" -> {ast.unparse(item.returns)}"

                        doc = get_docstring(item).strip()
                        if doc:
                            lines.append(f"- `{sig}` — {doc}")

    return "\n".join(lines)

def process_directory(directory):
    results = []
    for filename in sorted(os.listdir(directory)):
        if filename.endswith(".py"):
            filepath = os.path.join(directory, filename)
            res = parse_module(filepath)
            if res:
                results.append(res)
    return "\n\n".join(results)

