        type_part = f": {arg_type}" if arg_type else ""

        default_part = ""
        num_defaults = len(node.args.defaults)
        if i >= len(node.args.args) - num_defaults:
            default_val = ast.unparse(node.args.defaults[i - (len(node.args.args) - num_defaults)])
            default_part = f" = {default_val}"

