            default_part = f" = {default_val}"

        args_list.append(f"{arg_name}{type_part}{default_part}")

    # vararg
    if node.args.vararg:
        arg = node.args.vararg
        arg_name = arg.arg
        arg_type = ast.unparse(arg.annotation) if arg.annotation else ""
        type_part = f": {arg_type}" if arg_type else ""
        args_list.append(f"*{arg_name}{type_part}")

    # kwarg
    if node.args.kwarg:
        arg = node.args.kwarg
        arg_name = arg.arg
        arg_type = ast.unparse(arg.annotation) if arg.annotation else ""
        type_part = f": {arg_type}" if arg_type else ""
        args_list.append(f"**{arg_name}{type_part}")

    args_str = ", ".join(args_list)
    sig = f"{prefix}{name}({args_str})"
    if node.returns:
        sig += f" -> {ast.unparse(node.returns)}"
